    Bug 1980843 - Fix parsing of double quotes in -compose command line arguments. r=mkmelin


    The GetArgs() function in MsgComposeCommands.js previously only stripped
    single quotes from command-line parameters. If a parameter like a `to`
    address was wrapped in double quotes (e.g., to="foo@example.org"), the
    trailing quote was left attached to the value, causing email validation
    failures in the compose window.

    Double quotes are necessary for external wrappers like xdg-email
    because single-quoted arguments completely bypass the decodeURIComponent()
    step in Thunderbird's legacy parser, breaking URL-encoded characters.

    This patch explicitly strips surrounding double quotes before passing the
    argument to decodeURIComponent(). This ensures that multiple addresses and
    URL-encoded strings are handled correctly without leaving trailing quotes.

    Differential Revision: https://phabricator.services.mozilla.com/D294289

diff --git a/mail/components/compose/content/MsgComposeCommands.js b/mail/components/compose/content/MsgComposeCommands.js
index a95fad76e6b..d2746244f1f 100644
--- a/mail/components/compose/content/MsgComposeCommands.js
+++ b/mail/components/compose/content/MsgComposeCommands.js
@@ -3185,8 +3185,17 @@ function GetArgs(originalData) {
     var argname = pairs[i].substring(0, pos);
     var argvalue = pairs[i].substring(pos + 1);
     if (argvalue.startsWith("'") && argvalue.endsWith("'")) {
+      // Single quotes act as a raw literal escape. We strip the quotes
+      // but do not decode. This is especially important for the 'body'
+      // argument ensuring unaltered content.
       args[argname] = argvalue.substring(1, argvalue.length - 1);
     } else {
+      // Double quotes must be stripped to prevent validation errors (such as
+      // trailing quotes in email addresses), but the contents still need to be
+      // URI decoded to support tools like xdg-email.
+      if (argvalue.startsWith('"') && argvalue.endsWith('"')) {
+        argvalue = argvalue.substring(1, argvalue.length - 1);
+      }
       try {
         args[argname] = decodeURIComponent(argvalue);
